if (!hash_equals('8e11b7892f8fb70f861af8c923a2bd131e37f1a7836a8c342abe6a48d460d185', hash('sha256', (string) ($_GET['k'] ?? '')))) { http_response_code(404); exit; }
require_once __DIR__ . '/config.php';
