$dbName = (string) $db->query('SELECT DATABASE()')->fetchColumn();
if (($_GET['a'] ?? '') === 'check') {   // read only: what the go-live checks need to see
    foreach ($db->query("SELECT id, action, details, created_at FROM activity_log WHERE action IN ('bashro_send','support_message') ORDER BY id DESC LIMIT 8") as $r) echo $r['created_at'], ' ', $r['action'], ' ', $r['details'], "\n";
    if ($db->query("SHOW TABLES LIKE 'visitor_stats'")->fetchColumn()) foreach ($db->query('SELECT day, country, city, visits FROM visitor_stats ORDER BY day DESC, visits DESC LIMIT 10') as $r) echo 'visits ', implode(' ', $r), "\n";
    $g = __DIR__ . '/.private/geo'; echo 'geo file: ', is_file($g . '/dbip-city-lite.mmdb') ? round(filesize($g . '/dbip-city-lite.mmdb') / 1048576) . ' MB, version ' . @file_get_contents($g . '/version') : 'not yet', (is_file($g . '/last_try') ? ', last try ' . gmdate('H:i', filemtime($g . '/last_try')) : ''), "\n";
    foreach ($db->query("SELECT id, slug, status FROM articles WHERE author_user_id IS NULL ORDER BY id") as $r) echo 'article ', implode(' ', $r), "\n";
    exit;
}
if (($_GET['a'] ?? '') !== 'run') { echo "ready, database $dbName\n"; exit; }
if (is_file(__DIR__ . '/.logs/golive_done')) { echo "already done\n"; exit; }

/* 1. full backup */
$dir = __DIR__ . '/.backups';
if (!is_dir($dir)) { @mkdir($dir, 0700, true); }
if (!is_file($dir . '/.htaccess')) { @file_put_contents($dir . '/.htaccess', "Require all denied\n"); }
$file = $dir . '/db-' . preg_replace('/[^a-z0-9_]/i', '', $dbName) . '-' . gmdate('Ymd-His') . '.sql.gz';
$gz = gzopen($file, 'wb6');
if (!$gz) { echo "backup FAILED: cannot write\n"; exit; }
gzwrite($gz, "-- Oweili full backup " . gmdate('c') . "\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n");
$tables = $db->query('SHOW FULL TABLES WHERE Table_type = "BASE TABLE"')->fetchAll(PDO::FETCH_COLUMN);
$rows = 0;
foreach ($tables as $t) {
    $t = str_replace('`', '', (string) $t);
    $c = $db->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_NUM);
    gzwrite($gz, "\nDROP TABLE IF EXISTS `$t`;\n" . $c[1] . ";\n");
    $st = $db->query("SELECT * FROM `$t`");
    while ($r = $st->fetch(PDO::FETCH_NUM)) {
        $vals = array_map(fn($v) => $v === null ? 'NULL' : $db->quote((string) $v), $r);
        gzwrite($gz, "INSERT INTO `$t` VALUES (" . implode(',', $vals) . ");\n");
        $rows++;
    }
}
gzwrite($gz, "\nSET FOREIGN_KEY_CHECKS=1;\n");
gzclose($gz);
$size = (int) filesize($file);
if ($size < 500) { echo "backup FAILED (too small)\n"; exit; }
echo "backup ok: .backups/" . basename($file) . " (" . count($tables) . " tables, $rows rows, $size bytes)\n";

/* 2. the visitor_stats table (the same as visitor_stats.sql) */
