  PRIMARY KEY (`day`, `country`, `city`), KEY `idx_visitor_stats_day` (`day`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";
try { $db->exec($sql); echo "ok: visitor_stats table\n"; } catch (Throwable $e) { echo "FAILED: visitor_stats :: " . $e->getMessage() . "\n"; exit; }

